import{_ as e,o as a,c as r,ah as o}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"March 12: The Witness Who Bit Back – Mattura vs. Hanger in the Inquiry Committee","description":"Christian Mattura engages in a fierce match with the ÖVP in the Pilnacek inquiry committee. A feast for any screenwriter.","frontmatter":{"title":"March 12: The Witness Who Bit Back – Mattura vs. Hanger in the Inquiry Committee","description":"Christian Mattura engages in a fierce match with the ÖVP in the Pilnacek inquiry committee. A feast for any screenwriter.","date":"2026-03-12T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/2026-03-12-mattura-u-ausschuss-match.md","filePath":"en/logbuch/2026-03-12-mattura-u-ausschuss-match.md"}'),n={name:"en/logbuch/2026-03-12-mattura-u-ausschuss-match.md"};function i(s,t,h,c,u,l){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="⚖️-march-12-the-witness-who-bit-back-–-mattura-vs-hanger-in-the-inquiry-committee" tabindex="-1">⚖️ March 12: The Witness Who Bit Back – Mattura vs. Hanger in the Inquiry Committee <a class="header-anchor" href="#⚖️-march-12-the-witness-who-bit-back-–-mattura-vs-hanger-in-the-inquiry-committee" aria-label="Permalink to &quot;⚖️ March 12: The Witness Who Bit Back – Mattura vs. Hanger in the Inquiry Committee&quot;">​</a></h1><p>While our project goes viral on Reddit, reality in the <strong>Pilnacek Inquiry Committee</strong> today (March 12, 2026) provided material that could hardly be better invented for a mockumentary.</p><h3 id="the-duel-christian-mattura-vs-andreas-hanger" tabindex="-1"><strong>The Duel: Christian Mattura vs. Andreas Hanger</strong> <a class="header-anchor" href="#the-duel-christian-mattura-vs-andreas-hanger" aria-label="Permalink to &quot;**The Duel: Christian Mattura vs. Andreas Hanger**&quot;">​</a></h3><p>At the center was <strong>Christian Mattura</strong>, the entrepreneur who had secretly recorded the now-legendary &quot;Pilnacek Tape.&quot; But anyone expecting a defensive witness was disappointed. Mattura immediately went into attack mode.</p><ul><li><strong>The Frontal Assault:</strong> In his opening statement, Mattura accused ÖVP faction leader <strong>Andreas Hanger</strong> of a &quot;befitting democratic understanding.&quot; He accused the ÖVP of deliberately discrediting witnesses to distract from their own scandals.</li><li><strong>The &quot;Hanger Scale&quot;:</strong> The mood was so toxic that SPÖ MP Kai Jan Krainer dryly remarked that Hanger&#39;s questions were at the bottom of a &quot;10-part Hanger scale.&quot;</li><li><strong>&quot;Is that a threat?&quot;:</strong> When Hanger tried to use Mattura&#39;s background in the gambling sector against him, he coolly countered with the question: &quot;Is that a threat?&quot;. A moment that perfectly reflects the atmosphere in the committee.</li></ul><h3 id="new-details-on-the-disappeared-laptop" tabindex="-1"><strong>New Details on the &quot;Disappeared Laptop&quot;</strong> <a class="header-anchor" href="#new-details-on-the-disappeared-laptop" aria-label="Permalink to &quot;**New Details on the &quot;Disappeared Laptop&quot;**&quot;">​</a></h3><p>Mattura also brought explosive new rumors into play. He claimed to have heard from a confidante that Federal Police Director Michael Takacs had allegedly said that Pilnacek&#39;s laptop had to <strong>&quot;disappear.&quot;</strong> There was also talk of mysterious sums of money from Dubai.</p><h3 id="significance-for-the-horten-mystery" tabindex="-1"><strong>Significance for the &quot;Horten Mystery&quot;</strong> <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;**Significance for the &quot;Horten Mystery&quot;**&quot;">​</a></h3><p>This day in the inquiry committee is <strong>content gold</strong> for us:</p><ol><li><strong>Character Study:</strong> Mattura is the prototype of the &quot;uncomfortable witness&quot; we need in Part 4.</li><li><strong>The Aesthetics of the Interrogative:</strong> The way questions are used as weapons (keyword Hanger) will be a central stylistic device in our courtroom scenes.</li><li><strong>The Tape Motif:</strong> Secret recordings are the ultimate tool against the &quot;Archive of Silence.&quot;</li></ol><hr><p><strong>&quot;In a system based on silence, the secret microphone is the only speaker of the truth.&quot;</strong></p><p>👉 <a href="/en/recherche/christian-mattura-pilnacek-tape.html">More about the Pilnacek Tape and Christian Mattura</a> 👉 <a href="/en/logbuch/">Back to the Logbook Index</a></p><hr><p><em>Reporting from March 12, 2026. Reality writes the best screenplay.</em></p>',15)])])}const g=e(n,[["render",i]]);export{m as __pageData,g as default};
